#!/bin/bash# Spara som t.ex. \~/usb-gadget.sh och gör körbar (chmod +x)CONFIGFS=/sys/kernel/configGADGET=$CONFIGFS/usb_gadget/ally_gadget# Skapa gadgetmkdir -p $GADGETcd $GADGET# Grundinfo (ändra vid behov)echo 0x1d6b > idVendor     # Linux Foundationecho 0x0104 > idProduct    # Multifunction Composite Gadgetecho 0x0200 > bcdDeviceecho 0x0200 > bcdUSB# Strängarmkdir -p strings/0x409echo "CachyOS Ally" > strings/0x409/serialnumberecho "xAI" > strings/0x409/manufacturerecho "ROG Ally Gadget" > strings/0x409/product# Konfigurationmkdir -p configs/c.1/strings/0x409echo "Config 1: ECM/RNDIS" > configs/c.1/strings/0x409/configurationecho 250 > configs/c.1/MaxPower# Lägg till funktionermkdir -p functions/rndis.usb0     # Eller ecm.usb0ln -s functions/rndis.usb0 configs/c.1/# Aktivera på UDC (byt till din UDC från ls /sys/class/udc/)UDC_NAME=$(ls /sys/class/udc/ | head -n1)echo $UDC_NAME > UDC
